package textenc

import (
	"os"
	"testing"

	"strix-halo-vulkan/safetensors"
	"strix-halo-vulkan/vk"
	"strix-halo-vulkan/zimage/qwen"
)

const strixHaloDeviceID = 0x1586

func newTestDevice(t *testing.T) (*vk.Device, func()) {
	t.Helper()
	inst, err := vk.NewInstance("qi21-textenc-test")
	if err != nil {
		t.Skipf("no Vulkan instance: %v", err)
	}
	devices, err := inst.PhysicalDevices()
	if err != nil || len(devices) == 0 {
		inst.Destroy()
		t.Skipf("no Vulkan devices: %v", err)
	}
	phys := &devices[0]
	for i := range devices {
		if devices[i].DeviceID == strixHaloDeviceID {
			phys = &devices[i]
			break
		}
	}
	qf, err := phys.ComputeQueueFamily()
	if err != nil {
		inst.Destroy()
		t.Skipf("no compute queue: %v", err)
	}
	sgs, err := phys.SubgroupSizeControl()
	if err != nil {
		inst.Destroy()
		t.Skipf("no subgroup size control query: %v", err)
	}
	dev, err := vk.NewDevice(phys, qf, vk.DeviceFeatures{
		Float16: true, CoopMatrix: true, SubgroupSizeControl: sgs.Supported,
	})
	if err != nil {
		inst.Destroy()
		t.Skipf("no device: %v", err)
	}
	t.Logf("device: %s", phys.Name)
	return dev, func() { dev.Destroy(); inst.Destroy() }
}

// The fp16 bounds are measured, and the story behind them matters (all
// numbers 2026-09-20, TestGPULadder and the torch probes beside it):
//
// This checkpoint's residual stream grows a ~13k massive-activation channel
// at layer 6 (and again at 16), carries it flat for 18 layers, and *cancels*
// it in layers 34-35 — the two layers Z-Image's hidden_states[-2] never ran,
// which is why zimage/qwen's fp16 path could hold 6e-3 and this one cannot.
// Every reduced-precision pass through the FFN injects ~5e-4 of bulk
// rounding variance into that channel (keeping just the spike elements exact
// measurably does NOT help), and when the channel collapses the carried
// error surfaces: rel 0.024 on a real prompt, 0.21 elementwise on the
// all-template empty prompt whose rows are mostly cancellation residue.
//
// Priced against the model's own deployment: the *official* bf16 pipeline
// deviates from fp32 by rel 2.0 (max abs 204) through the same mechanism —
// two orders of magnitude beyond this path. If Q3/Q6 ever show prompt
// adherence suffering, the known lever is an fp32-activation GEMM arm for
// the encoder, and at prompt-sized M (~40 rows) the encoder is
// weight-bandwidth-bound, so that arm would cost little; it is not built
// because nothing yet shows it is needed.
const (
	gpuTol      = 3e-2 // en/cjk: measured 0.024-0.027
	gpuEmptyTol = 0.25 // empty prompt: measured 0.214, residue-dominated
)

// TestGPUEncoder is Q1's GPU acceptance gate: zimage/qwen's GPUEncoder,
// unchanged, over the Qwen3-VL config — all 36 layers, no final norm — for
// the three dumped prompts. ~15 GB of fp16 banks, staged one layer at a
// time.
func TestGPUEncoder(t *testing.T) {
	if testing.Short() {
		t.Skip("stages 15 GB of fp16 banks")
	}
	m := loadManifest(t)
	if _, err := os.Stat(encoder); err != nil {
		t.Skipf("no text encoder checkpoint at %s", encoder)
	}
	cfg, err := LoadConfig(encoder)
	if err != nil {
		t.Fatal(err)
	}
	set, err := safetensors.OpenSet(encoder)
	if err != nil {
		t.Fatal(err)
	}
	defer set.Close()

	dev, done := newTestDevice(t)
	defer done()
	g, err := qwen.NewGPUEncoder(dev, set, cfg, cfg.NumLayers, 512, nil)
	if err != nil {
		t.Fatal(err)
	}
	defer g.Destroy()

	for _, label := range []string{"en", "cjk", "empty"} {
		p := m.Prompts[label]
		out, err := g.Forward(p.IDs)
		if err != nil {
			t.Fatal(err)
		}
		tol := gpuTol
		if label == "empty" {
			tol = gpuEmptyTol
		}
		if label == "en" {
			compareAt(t, "en_last_prenorm", out, loadRef(t, m, "en_last_prenorm"), tol)
		}
		embeds, err := Drop(out, m.DropIdx)
		if err != nil {
			t.Fatal(err)
		}
		compareAt(t, label+"_prompt_embeds", embeds, loadRef(t, m, label+"_prompt_embeds"), tol)
	}
}
	// stagedLayout is how the weights were written; kernelLayout is what
	// every rung reads. They differ only under the wrongBLayout control,
	// which is the whole point of it.
	stagedLayout         int
	ldaDim, ldaQ, ldaFFN int

	embedRows int
	embed     []float32

	wCos, wSin uint32
	w          []layerWeights

	// fp32 activation arena.
	aX, aQ, aK, aV, aCtx, aAttn uint32
	aGate, aUp, aFF             uint32
	actElems                    int

	// fp16 activation arena.
	hA, hQ, hK, hV, hCtx, hFFN uint32
	hElems                     int
}

// NewGPUEncoder builds the encoder: layers decoder layers out of set, sized
// for at most maxTokens. plan may be nil for DefaultGEMMPlan.
//
// set is read during construction only -- the embedding table is copied to
// the host as fp32 (1.56 GB) and every projection is narrowed into a bank --
// so the caller may close it afterwards, as the DiT's stack allows.
func NewGPUEncoder(dev *vk.Device, set *safetensors.Set, cfg *Config, layers, maxTokens int, plan GEMMPlan) (*GPUEncoder, error) {
	return newEncoder(dev, set, cfg, layers, maxTokens, plan, controls{}, maxBankBytes)
}

func newEncoder(dev *vk.Device, set *safetensors.Set, cfg *Config, layers, maxTokens int, plan GEMMPlan, ctl controls, bankBytes int) (*GPUEncoder, error) {
	explicitPlan := plan
	if layers <= 0 || layers > cfg.NumLayers {
		return nil, fmt.Errorf("qwen: asked for %d of %d layers", layers, cfg.NumLayers)
	}
	if maxTokens <= 0 {
		return nil, fmt.Errorf("qwen: maxTokens is %d", maxTokens)
	}
	if plan == nil {
		plan = DefaultGEMMPlan()
	}
	ok, err := canWMMA(dev)
	if err != nil {
		return nil, err
	}
	if !ok {
		return nil, fmt.Errorf("qwen: this device has no 16x16x16 fp16 cooperative matrix; the encoder graph needs one")
	}
	if cfg.NumHeads%cfg.NumKVHeads != 0 {
		return nil, fmt.Errorf("qwen: %d heads do not divide into %d kv heads", cfg.NumHeads, cfg.NumKVHeads)
	}
	if cfg.HeadDim != headDim {
		return nil, fmt.Errorf("qwen: head dim %d, but the kernels are built for %d", cfg.HeadDim, headDim)
	}
	g := &GPUEncoder{
		dev:     dev,
		cfg:     cfg,
		ctl:     ctl,
		plan:    plan,
		pipes:   make(map[string]*vk.ComputePipeline),
		kernels: make(map[GEMMKernel]gemmVariant),
		tokens:  maxTokens,
		rows:    maxTokens,
		ldaDim:  cfg.HiddenSize + gemmPad,
		ldaQ:    cfg.NumHeads*cfg.HeadDim + gemmPad,
		ldaFFN:  cfg.IntermediateSize + gemmPad,
	}
	if err := g.chooseAttention(); err != nil {
		g.Destroy()
		return nil, err
	}
	// The run length is padded to the largest tile any dispatch covers: the
	// GEMM's BM, and the attention kernel's key block, which reads whole
	// blocks of the packed planes. One number serves both.
	//
	// Every rung is built and every rung reads the same fragment-tiled
	// weight, so the plan can be changed after construction (SetPlan) without
	// restaging 7 GB -- which is what makes the ladder in cmd/textenc one
	// load instead of seven. The arenas are therefore sized for the widest
	// tile in the table rather than for the plan.
	g.stagedLayout = 2
	if ctl.wrongBLayout {
		g.stagedLayout = 0
	}
	arenaAlign := g.attn.keyBlock()
	for _, v := range gemmVariants {
		if v.layout == kernelLayout {
			g.kernels[v.name] = v
			arenaAlign = max(arenaAlign, v.bm)
		}
	}
	if err := g.SetPlan(plan); err != nil {
		g.Destroy()
		return nil, err
	}
	// A caller that named a plan meant it; only the default schedules.
	g.AutoPlan = explicitPlan == nil
	g.arenaRows = roundUp(maxTokens, arenaAlign)

	if err := g.layoutWeights(layers, bankBytes); err != nil {
		g.Destroy()
		return nil, err
	}
	if err := g.allocActivations(); err != nil {
		g.Destroy()
		return nil, err
	}
	if err := g.build(); err != nil {
		g.Destroy()
		return nil, err
	}
	if err := g.stageWeights(set, layers); err != nil {
		g.Destroy()
		return nil, err
	}
	return g, nil
}

// headDim is compiled into the pack and attention shaders.

