	g, err := qwen.NewGPUEncoder(dev, set, cfg, Layers, 1024, nil)
	if err != nil {
		t.Fatal(err)
	}
	defer g.Destroy()
	for _, label := range []string{"en", "cjk", "readme"} {
		out, err := g.Forward(m.Prompts[label].IDs)
		if err != nil {
			t.Fatal(err)
		}
		want := encMat(t, m, label+"_fp32")
