		brel, babs, _ := gap(encMat(t, m, label+"_bf16"), want)
		t.Logf("%-7s %4d tokens: fp16 rel %.3g (max abs %.4g, rms %.3g); official bf16 rel %.3g (max abs %.4g)",
			label, out.Rows, rel, maxAbs, rms, brel, babs)
		if rel > gpuTol || math.IsNaN(rel) {
			t.Errorf("%s: rel %.3g > %.0e", label, rel, gpuTol)
		}
	}
}

