	Bias []float32
}

// Apply runs the projection over every row of x.
func (l *Linear) Apply(x *qwen.Mat) (*qwen.Mat, error) {
	out, err := l.Linear.Apply(x)
	if err != nil || l.Bias == nil {
		return out, err
	}
