#version 450
#extension GL_EXT_shader_16bit_storage : require
#extension GL_EXT_shader_explicit_arithmetic_types_float16 : require
#extension GL_EXT_control_flow_attributes : enable
// The whole of what happens to q and k between their projection and
// attention, in one pass: the per-head RMS norm, the 3-D rotary embedding,
// the softmax scale, and the narrowing into dit_pack_f16.comp's fragment-tile
// layout.
//
// Unfused, that is three dispatches and 346 MB of traffic per operand at 4096
// tokens (read 63, write 63, read 63, write 63, read 63, write 31) for 63 MB
// of input and 31 MB of output. None of them does arithmetic worth the name
// and all three are at the bus, so the fusion is worth what the round trips
// cost -- measured at 1.83 ms -> 0.55 ms per operand
// (research/stage-4-dit-graph.md).
//
// It is possible at all because the three steps have the same natural unit as
// the pack already does: a **head of one token**. The RMS norm is per head
// (128 wide, not 3840 -- normalising over the full width is a plausible port
// bug that changes the output by 2.4x), the rotation pairs components 2j and
// 2j+1 within a head, and a fragment tile column is a slice of one head. So a
// workgroup that owns 16 tokens of one head owns everything all three steps
// need, and the intermediate never leaves LDS.
//
// The unfused kernels stay: they are three separately validated stages, and
// GPUBlock keeps a path through them so the fused output can be checked
// against the thing it replaces rather than only against the reference.
#include "dit_common.glsl"
layout(binding = 2) writeonly buffer HAct { float16_t hact[]; };
#define TILE 16
#ifndef HEAD_DIM
#define HEAD_DIM 128
#endif
#define HDT (HEAD_DIM / TILE)
#define PAIRS (HEAD_DIM / 2)
#define WG 256
#define LANES (WG / TILE)   // lanes cooperating on one token's head
// Token tiles per workgroup, as in dit_pack_f16.comp and for the same reason
// (IMAGE.md Q9): one tile is 2048 elements over 256 threads, and the DiT's
// profile measured this pass at 46 GB/s against a ~190 GB/s bus. TPW = 1 is
// every pre-existing build, unchanged; pc.span carries the tile count so a
// grid rounded up to TPW cannot overrun into the next head's plane.
#ifndef TPW
#define TPW 1
#endif
layout(local_size_x = WG) in;
shared float rows[TILE * HEAD_DIM];
shared float partial[WG];
shared float inv[TILE];
void main() {
    uint head = gl_WorkGroupID.y;
    uint tid = gl_LocalInvocationID.x;
  for (uint slab = 0u; slab < uint(TPW); ++slab) {
    uint tt = gl_WorkGroupID.x * uint(TPW) + slab;
    if (pc.span != 0u && tt >= pc.span) {
        return;
    }
    uint tok0 = tt * TILE;
    if (slab > 0u) {
        barrier();
    }
    // Coalesced in: consecutive lanes read consecutive components of one
    // token. Tokens past the sequence are zeroed rather than skipped -- the
    // attention kernel reads the padding and a pad key has to score
    // something finite.
    for (uint i = tid; i < TILE * HEAD_DIM; i += WG) {
        uint m = i / HEAD_DIM, d = i % HEAD_DIM;
        uint token = tok0 + m;
        rows[i] = (token < pc.tokens)
            ? act[pc.inOff + token * pc.dim + head * HEAD_DIM + d]
            : 0.0;
    }
    barrier();
    // The per-head RMS: LANES lanes per token row, each summing HEAD_DIM/LANES
    // components at stride LANES, then a tree over the lanes. Consecutive
    // lanes touch consecutive LDS addresses, so the stride costs no bank
    // conflicts.
    uint m = tid / LANES, lane = tid % LANES;
    float s = 0.0;
    for (uint d = lane; d < HEAD_DIM; d += LANES) {
        float v = rows[m * HEAD_DIM + d];
        s += v * v;
    }
    partial[tid] = s;
    barrier();
    [[unroll]] for (uint step = LANES / 2u; step > 0u; step >>= 1) {
        if (lane < step) {
            partial[tid] += partial[tid + step];
        }
        barrier();
    }
    if (lane == 0u) {
        // A pad row is all zeros; giving it inv = 0 keeps the zeros zero
        // instead of propagating the 1/sqrt(eps) a real norm would produce.
        inv[m] = (tok0 + m < pc.tokens)
            ? inversesqrt(partial[tid] / float(HEAD_DIM) + uintBitsToFloat(pc.eps))
            : 0.0;
    }
    barrier();
    // Norm weight, rotation and scale, in place in LDS. One thread owns
    // TILE*PAIRS/WG complex pairs; both divisors are compile-time powers of
    // two. The rotation is (2j, 2j+1) -- see dit_rope.comp for why that
    // matters -- and the cos/sin tables are indexed by the token alone, since
    // every head shares them.
    for (uint p = tid; p < TILE * PAIRS; p += WG) {
        uint r = p / PAIRS, j = p % PAIRS;
        uint token = tok0 + r;
        uint base = r * HEAD_DIM + 2u * j;
        float re = rows[base] * inv[r] * wbuf[pc.aux2 + 2u * j];
        float im = rows[base + 1u] * inv[r] * wbuf[pc.aux2 + 2u * j + 1u];
        float c = 0.0, sn = 0.0;
        if (token < pc.tokens) {
            c = wbuf[pc.wOff + token * PAIRS + j];
            sn = wbuf[pc.aux0 + token * PAIRS + j];
        }
        float sc = uintBitsToFloat(pc.scale);
        rows[base] = (re * c - im * sn) * sc;
        rows[base + 1u] = (re * sn + im * c) * sc;
    }
    barrier();
    // Coalesced out: consecutive lanes write consecutive halves of one 512 B
    // fragment tile. Tile (t, c) of a head holds token rows 16t.. and
    // component columns 16c.., element (token, component) at m*16 + k, which
    // is what a row-major fragment load of stride 16 reads.
    uint outBase = pc.outOff + (head * pc.aux1 / TILE + tt) * (HDT * TILE * TILE);
    for (uint o = tid; o < HDT * TILE * TILE; o += WG) {
        uint c = o / (TILE * TILE);
        uint rem = o % (TILE * TILE);
        hact[outBase + o] = float16_t(rows[(rem / TILE) * HEAD_DIM + c * TILE + rem % TILE]);
    }
  }
}
#version 450
#extension GL_EXT_shader_16bit_storage : require
#extension GL_EXT_shader_explicit_arithmetic_types_float16 : require
// Pack one fp32 [tokens, heads*headDim] activation into the fp16 fragment-tile
// layout dit_attention_wmma.comp's cooperative-matrix loads want.
//
// The layout is the whole point of this shader, and it is IDEAS §5.1b's
// coverage law applied to a `coopMatLoad`. A 16x16 fp16 fragment holds 32 bytes
// of each of the 16 rows it touches, so reading one out of a matrix stored with
// any natural row stride puts 16 chunks of 32 B, one stride apart, in a single
// instruction: the contiguous run in flight is 32 B against a gcd of 256 or
// more, i.e. an eighth of the bus or less. That is exactly the regime the GEMM
// ablation measured 2-4x in (shaders/gemm_wmma.comp's HOIST_A/HOIST_B), and
// measured here first: with q, k and v in their natural per-head layouts the
// WMMA attention kernel reached 1.56x the scalar one instead of the order of
// magnitude the matrix cores are worth, and every tile geometry tied, which is
// the signature of a kernel bound by neither its registers nor its MMA issue.
//
// So the fragments are stored *as fragments*. Tile (t, c) of a head -- token
// rows 16t..16t+15, component columns 16c..16c+15 -- is one contiguous 512 B
// block, and `coopMatLoad(..., stride 16)` reads it with full coverage and no
// hoisting, no LDS staging and no extra registers in the kernel that consumes
// it. Consecutive c are adjacent blocks, which is the order the kernel walks.
//
// Two modes, because the two GEMMs of attention reduce over different axes and
// the hardware operand layout is K-contiguous for both operands:
//
//   mode 0 stores (token, component) at m*16 + k. That serves q as the A
//     operand of q.k^T, read row-major, *and* k as its B operand, read
//     column-major -- the reduction axis is the component for both, so one
//     layout does for both.
//   mode 1 stores (token, component) at hd*16 + m, i.e. each tile transposed.
//     That serves v as the B operand of p.v, whose reduction axis is the token.
//
// Which is the same trick dit_transpose_k.comp plays for the scalar kernel,
// moved to the other operand and down to tile granularity.
//
// The transpose goes through LDS so that both sides of it are coalesced: one
// workgroup owns 16 tokens of one head, reads them as 16 contiguous rows of
// headDim floats, and writes HDT contiguous 512 B tiles. Neither the read nor
// the write is the 32-byte-run pattern this file exists to avoid.
//
// Scale folds into the pack: q carries 1/sqrt(headDim) * log2(e) so the
// kernel's softmax can use exp2 instead of exp, which on this ISA is one
// instruction instead of a multiply and one.
#include "dit_common.glsl"
layout(binding = 2) buffer HAct { float16_t hact[]; };
#define TILE 16
#ifndef HEAD_DIM
#define HEAD_DIM 128
#endif
#define HDT (HEAD_DIM / TILE)
// SRC_HEAD_DIM is the head width in the fp32 source when it is not a
// multiple of the tile: qwen3.8-flash-next's vision tower has 72-wide heads,
// packed here as 80 with the last eight components zero (LLM-VISION.md V4).
// Zero columns contribute nothing to q.k and produce zero context columns
// from v, which the output projection's zero weight columns then ignore. The
// source row stride is still pc.dim. Every other build leaves it at HEAD_DIM.
#ifndef SRC_HEAD_DIM
#define SRC_HEAD_DIM HEAD_DIM
#endif
// A per-head bias vector added to every token before the scale, which is what
// parakeet's Transformer-XL attention wants of q: it adds a learned bias_u to
// the query before the content score (parakeet/encoder.go), and this pass is
// already reading q element by element, so folding it in costs nothing and
// saves a round trip of the tensor. The vector is [heads*headDim] fp32 in the
// weight arena at pc.wOff, and BIAS=0 -- every existing build -- does not read
// it.
#ifndef BIAS
#define BIAS 0
#endif
#if BIAS
#define QBIAS(head, d) + wbuf[pc.wOff + (head) * HEAD_DIM + (d)]
#else
#define QBIAS(head, d)
#endif
#define WG 256
// Token tiles per workgroup (IMAGE.md Q9). One tile is 16 x headDim = 2048
// elements, which at WG = 256 is eight elements a thread and two barriers --
// too little to keep the loads in flight, and the DiT's profile said so: this
// pass moved 102 MB in 2.3 ms, 44 GB/s against the ~190 the SwiGLU beside it
// reaches. TPW tiles per workgroup multiply the work per thread and divide
// the launches by the same factor without changing a byte of the layout.
