a2='''#define PAIRS (HEAD_DIM / 2)'''
b2='''#ifndef ROPE_WIDTH
#define ROPE_WIDTH 96
#endif
#define HALF (ROPE_WIDTH / 2)
#define PASS (HEAD_DIM - ROPE_WIDTH)'''
assert a2 in s; s=s.replace(a2,b2)
s=s.replace('#version 450\n','#version 450\n'+head,1)
open('h3_qk_pack.comp','w').write(s)
